package com.manishrawat.realestate.filter; import com.manishrawat.realestate.dao.*; import com.manishrawat.realestate.model.User; import jakarta.servlet.*; import jakarta.servlet.annotation.WebFilter; import jakarta.servlet.http.*; import java.io.*;
@WebFilter(urlPatterns={"/dashboard","/logout","/property","/application","/agreement","/messages","/notifications","/profile","/admin"}) public class AuthFilter implements Filter {public void doFilter(ServletRequest req,ServletResponse res,FilterChain chain)throws IOException,ServletException{HttpServletRequest r=(HttpServletRequest)req;HttpServletResponse s=(HttpServletResponse)res;HttpSession session=r.getSession(false);if(session==null||session.getAttribute("user")==null){s.sendRedirect(r.getContextPath()+"/");return;}s.setHeader("Cache-Control","no-store");try{User old=(User)session.getAttribute("user");User u=new UserDAO().findById(old.getId());if(u==null||!u.isActive()){session.invalidate();s.sendRedirect(r.getContextPath()+"/");return;}session.setAttribute("user",u);if(!"ADMIN".equals(u.getRole())&&!r.getServletPath().equals("/logout")&&Boolean.parseBoolean(new SettingsDAO().all().getOrDefault("maintenance_mode","false"))){s.sendError(503,"The site is temporarily in maintenance mode.");return;}chain.doFilter(req,res);}catch(Exception e){throw new ServletException("Unable to verify your account and system access.",e);}}}
